"use client";
// @zeus-internal
import { changeParts, COMPARISON_LABEL, formatValue, type HeaderMetric, METRICS } from "./06-headers/data";
import { NumberTicker } from "./06-headers/number-ticker";
export default function KpiOverviewHeaders() {
    return (<div className="art:w-full art:max-w-7xl">
      <section aria-label="Key performance indicators" className="art:@container art:w-full art:min-w-0">
        <dl className="art:grid art:grid-cols-1 art:gap-3 art:@2xl:grid-cols-2 art:@4xl:grid-cols-4">
          {METRICS.map((metric) => (<MetricCard key={metric.id} metric={metric}/>))}
        </dl>
      </section>
    </div>);
}
function MetricCard({ metric }: {
    metric: HeaderMetric;
}) {
    const change = changeParts(metric);
    return (<div className="art:flex art:min-w-0 art:flex-col art:rounded-3xl art:border art:border-border art:p-1.5 art:bg-muted">
      <dt className="art:flex art:items-center art:gap-3 art:px-4 art:py-3 art:text-muted-foreground">
        <span aria-hidden="true" className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border art:[&>svg]:size-4">
          {metric.icon}
        </span>
        <span className="art:font-mono art:font-medium art:uppercase art:tracking-tight art:whitespace-nowrap art:text-xl">{metric.label}</span>
      </dt>
      <dd className="art:flex art:flex-1 art:flex-col art:justify-between art:gap-4 art:rounded-2xl art:bg-background art:p-4">
        <div className="art:flex art:min-h-9 art:items-center">
          <div className="art:flex art:min-w-0 art:flex-wrap art:items-center art:gap-x-2 art:gap-y-1">
            <NumberTicker text={formatValue(metric)} className="art:inline-flex art:items-baseline art:whitespace-nowrap art:text-2xl art:font-medium art:tabular-nums art:tracking-tight art:text-foreground art:@5xl:text-3xl"/>
          </div>
        </div>
        <p className="art:flex art:flex-wrap art:items-center art:gap-x-1.5 art:gap-y-1 art:text-xs art:text-muted-foreground">
          <NumberTicker text={change.text} prefix={change.prefix} suffix={change.suffix} className={`art:inline-flex art:items-baseline art:whitespace-nowrap art:font-medium art:tabular-nums ${change.positive ? "art:text-success-foreground" : "art:text-destructive"}`}/>
          <span>{COMPARISON_LABEL}</span>
        </p>
      </dd>
    </div>);
}

// @zeus-internal
import type { ReactNode } from "react";
import { CalendarCheckIcon, Repeat2Icon, RotateCcwIcon, UserRoundCheckIcon } from "./icons";
export interface HeaderMetric {
    id: string;
    label: string;
    icon: ReactNode;
    value: number;
    previous: number;
    format?: {
        style?: "currency" | "percent";
        decimals?: number;
    };
    increaseIsPositive?: boolean;
}
export const COMPARISON_LABEL = "over last month";
export const METRICS: readonly HeaderMetric[] = [
    {
        id: "bookings",
        label: "Bookings",
        icon: <CalendarCheckIcon />,
        value: 38460,
        previous: 34100,
        format: { style: "currency" },
    },
    {
        id: "renewals",
        label: "Renewals",
        icon: <Repeat2Icon />,
        value: 128,
        previous: 116,
    },
    {
        id: "refunds",
        label: "Refunds",
        icon: <RotateCcwIcon />,
        value: 840,
        previous: 1020,
        format: { style: "currency" },
        increaseIsPositive: false,
    },
    {
        id: "retention",
        label: "Retention",
        icon: <UserRoundCheckIcon />,
        value: 94.2,
        previous: 92.8,
        format: { style: "percent", decimals: 1 },
    },
];
export function formatValue(metric: HeaderMetric): string {
    const decimals = metric.format?.decimals ?? 0;
    const digits: Intl.NumberFormatOptions = { minimumFractionDigits: decimals, maximumFractionDigits: decimals };
    if (metric.format?.style === "currency") {
        return new Intl.NumberFormat("en-US", { ...digits, style: "currency", currency: "USD" }).format(metric.value);
    }
    if (metric.format?.style === "percent") {
        return `${new Intl.NumberFormat("en-US", digits).format(metric.value)}%`;
    }
    return new Intl.NumberFormat("en-US", digits).format(metric.value);
}
export interface ChangeParts {
    text: string;
    prefix?: string;
    suffix: string;
    positive: boolean;
}
export function changeParts(metric: HeaderMetric): ChangeParts {
    const percentPoints = metric.format?.style === "percent";
    const delta = percentPoints
        ? metric.value - metric.previous
        : ((metric.value - metric.previous) / Math.abs(metric.previous)) * 100;
    const text = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(delta);
    const increaseIsPositive = metric.increaseIsPositive ?? true;
    return {
        text,
        prefix: delta > 0 ? "+" : undefined,
        suffix: percentPoints ? " pp" : "%",
        positive: increaseIsPositive ? delta >= 0 : delta <= 0,
    };
}

